{
  "claims": [
    {
      "text": "Monitor blood glucose levels closely.",
      "action_type": "monitored",
      "target": "Glucose"
    },
    {
      "text": "Continue intravenous fluid administration.",
      "action_type": "therapy_continued",
      "target": "Bag 100 mL IV"
    },
    {
      "text": "Order a complete blood count (CBC) and differential.",
      "action_type": "ordered",
      "target": "Complete Blood Count (CBC) and Differential"
    },
    {
      "text": "Administer IV magnesium sulfate 4 gm if not already done.",
      "action_type": "administered",
      "target": "Magnesium Sulfate 4 gm IV"
    },
    {
      "text": "Monitor electrolyte levels, especially potassium and magnesium.",
      "action_type": "monitored",
      "target": "Electrolytes"
    },
    {
      "text": "Continue bisacodyl 10 mg PO/PR as needed.",
      "action_type": "therapy_continued",
      "target": "Bisacodyl 10 mg PO/PR"
    },
    {
      "text": "Administer lorazepam 0.5 mg IV if patient is anxious.",
      "action_type": "administered",
      "target": "Lorazepam 0.5 mg IV"
    },
    {
      "text": "Continue ketorolac 15 mg IV.",
      "action_type": "therapy_continued",
      "target": "Ketorolac 15 mg IV"
    },
    {
      "text": "Monitor respiratory rate and O2 saturation.",
      "action_type": "monitored",
      "target": "Respiratory Rate, O2 Saturation"
    },
    {
      "text": "Assess for signs of dehydration and ensure adequate fluid intake.",
      "action_type": "assessment_performed",
      "target": "Dehydration"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor INR and PT levels.",
      "action_type": "monitored",
      "target": "INR, PT"
    },
    {
      "text": "Evaluate and manage electrolyte imbalances.",
      "action_type": "monitored",
      "target": "Potassium, Sodium, Magnesium"
    },
    {
      "text": "Monitor vital signs for fluctuations.",
      "action_type": "monitored",
      "target": "Heart rate, Blood pressure, Respiratory rate, Oxygen saturation"
    },
    {
      "text": "Continue nutritional support.",
      "action_type": "therapy_continued",
      "target": "Parenteral nutrition"
    },
    {
      "text": "Assess oral intake and consider nasogastric feeding if necessary.",
      "action_type": "assessment_performed",
      "target": "Oral intake"
    },
    {
      "text": "Monitor for signs of infection or sepsis.",
      "action_type": "monitored",
      "target": "Fever, WBC count, Lactate"
    },
    {
      "text": "Check for signs of dehydration.",
      "action_type": "monitored",
      "target": "Urine output, Skin turgor"
    },
    {
      "text": "Continue pain management.",
      "action_type": "therapy_continued",
      "target": "Acetaminophen"
    },
    {
      "text": "Monitor for signs of pulmonary complications.",
      "action_type": "monitored",
      "target": "Respiratory rate, O2 saturation"
    },
    {
      "text": "Evaluate the need for further antibiotic therapy.",
      "action_type": "assessment_performed",
      "target": "Levofloxacin, Metronidazole, Vancomycin"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor electrolyte levels, particularly potassium and sodium, closely over the next 24 hours.",
      "action_type": "monitored",
      "target": "Electrolytes"
    },
    {
      "text": "Continue monitoring vital signs, especially heart rate and blood pressure, for any significant fluctuations.",
      "action_type": "monitored",
      "target": "Vital signs"
    },
    {
      "text": "Administer IV fluids to maintain adequate hydration and stabilize electrolyte imbalances.",
      "action_type": "administered",
      "target": "IV fluids"
    },
    {
      "text": "Consider a detailed cardiac evaluation, including an ECG, given the elevated troponin levels and chest pain.",
      "action_type": "procedure_performed",
      "target": "ECG"
    },
    {
      "text": "Initiate a pain management plan to address the moderate to severe pain.",
      "action_type": "therapy_continued",
      "target": "Pain management"
    },
    {
      "text": "Monitor the patient for signs of respiratory distress, given the elevated respiratory rate and low oxygen saturation.",
      "action_type": "monitored",
      "target": "Respiratory status"
    },
    {
      "text": "Continue to monitor the patient for signs of infection, given the high WBC count and presence of hyaline casts in the urine.",
      "action_type": "monitored",
      "target": "Infection"
    },
    {
      "text": "Assess the patient’s nutritional status and consider a referral to a dietician if needed.",
      "action_type": "assessment_performed",
      "target": "Nutritional status"
    },
    {
      "text": "Continue to monitor the patient’s cognitive function using the CAM-ICU tool to assess for changes in mental status.",
      "action_type": "monitored",
      "target": "CAM-ICU"
    },
    {
      "text": "Monitor the patient for any signs of adverse reactions to current medications, particularly IV medications.",
      "action_type": "monitored",
      "target": "Medication side effects"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor hemoglobin and hematocrit levels closely due to significant anemia.",
      "action_type": "monitored",
      "target": "Hemoglobin, Hematocrit"
    },
    {
      "text": "Continue intravenous fluids to maintain hydration and electrolyte balance.",
      "action_type": "therapy_continued",
      "target": "IV fluids"
    },
    {
      "text": "Administer supplemental oxygen if oxygen saturation falls below 92%.",
      "action_type": "administered",
      "target": "Oxygen therapy"
    },
    {
      "text": "Assess for signs of infection given low white blood cell count.",
      "action_type": "assessment_performed",
      "target": "Infection"
    },
    {
      "text": "Consider starting iron supplementation due to anemia and low MCV.",
      "action_type": "therapy_continued",
      "target": "Iron supplementation"
    },
    {
      "text": "Continue monitoring for potential complications from prolonged ICU stay.",
      "action_type": "monitored",
      "target": "Complications"
    },
    {
      "text": "Assess patient for cognitive changes and provide appropriate support.",
      "action_type": "assessment_performed",
      "target": "Cognitive function"
    },
    {
      "text": "Continue current sedation regimen to maintain Richmond-RAS Scale at -2.",
      "action_type": "therapy_continued",
      "target": "Sedation"
    },
    {
      "text": "Check for and manage any potential hyperglycemia, especially if glucose levels are not within normal range.",
      "action_type": "monitored",
      "target": "Glucose levels"
    },
    {
      "text": "Monitor heart rate and blood pressure closely, addressing any alarms promptly.",
      "action_type": "monitored",
      "target": "Heart rate, Blood pressure"
    }
  ]
}

{
  "claims": [
    {
      "text": "Monitor vital signs and oxygen saturation closely.",
      "action_type": "monitored",
      "target": "vital_signs, O2_saturation"
    },
    {
      "text": "Continue intravenous vancomycin for suspected infection.",
      "action_type": "therapy_continued",
      "target": "vancomycin"
    },
    {
      "text": "Monitor electrolyte levels, particularly potassium and magnesium.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Consider ordering a chest X-ray to evaluate respiratory status.",
      "action_type": "ordered",
      "target": "chest_X-ray"
