    {
      "text": "Continue pain management with IV medications.",
      "action_type": "therapy_continued",
      "target": "pain_management"
    },
    {
      "text": "Monitor for signs of hypovolemia and consider fluid resuscitation if necessary.",
      "action_type": "monitored",
      "target": "hypovolemia"
    },
    {
      "text": "Order a complete blood count (CBC) and coagulation profile to evaluate hematological and coagulation status.",
      "action_type": "ordered",
      "target": "CBC, coagulation_profile"
    },
    {
      "text": "Assess the patient’s mobility and implement preventive strategies for pressure ulcers.",
      "action_type": "assessment_performed",
      "target": "mobility, pressure_ulcers"
    },
    {
      "text": "Continue mechanical ventilation support.",
      "action_type": "therapy_continued",
      "target": "ventilation"
    }
  ]
}

{
  "claims": [
    {
      "text": "Administer IV fluids to maintain fluid volume and blood pressure.",
      "action_type": "administered",
      "target": "IV fluids (Lactated Ringers, 0.9% Sodium Chloride)"
