      "text": "Administer IV bicarbonate to correct metabolic acidosis.",
      "action_type": "administered",
      "target": "Sodium Bicarbonate 50 mEq IV"
    },
    {
      "text": "Administer IV albumin to improve oncotic pressure and fluid balance.",
      "action_type": "administered",
      "target": "Albumin 25% (12.5g / 50mL) 25 g IV"
    },
    {
      "text": "Evaluate and manage potential causes of hyperbilirubinemia.",
      "action_type": "assessment_performed",
      "target": "Liver function tests, coagulation profile"
    },
    {
      "text": "Administer IV calcium to manage hypocalcemia.",
      "action_type": "administered",
      "target": "Calcium Gluconate 4 g IV"
    },
    {
      "text": "Monitor renal function (Creatinine, Urea Nitrogen) and adjust fluid management accordingly.",
      "action_type": "monitored",
      "target": "Renal function"
    },
    {
      "text": "Assess for signs of sepsis and initiate appropriate antimicrobial therapy if indicated.",
      "action_type": "assessment_performed",
      "target": "Sepsis"
    },
    {
      "text": "Continue monitoring for respiratory status and adjust ventilator settings as needed.",
      "action_type": "monitored",
      "target": "Respiratory status"
    }
  ]
